/**
 * Condition is a goal's verb, target and amount (GDD 11.2); empty fields
 * match anything.
 */
export interface Condition {
  verb: string;
  kind?: string;
  tag?: string;
  trait?: string;
  count: number /* int64 */;
  at?: string;
  hex?: Hex;
  within?: number /* int64 */;
  from?: string;
  field?: string;
  atLeast?: number /* int64 */;
  gauge?: string;
  line?: number /* int64 */;
  below?: boolean;
  who?: string;
  side?: string;
}
/**
 * GoalSpec is a goal as its poster specifies it.
 */
export interface GoalSpec {
  title: string;
  note?: string;
  issuer: string; // character, party, settlement, admin
  members?: string[];
  cond: Condition;
  reward: number /* int64 */;
  mode: string;
  cap?: number /* int64 */;
  lifetime: string;
  turnover: string;
  ticks?: number /* int64 */;
  even?: boolean;
  material?: string;
  units?: number /* int64 */;
}
/**
 * Goal is a posted goal as the board shows it.
 */
export interface Goal {
  id: string;
  title: string;
  note?: string;
  issuer: string; // its kind
  by: string; // who issued it, by name
  verb: string;
  what: string; // the condition in words
  where?: string;
  /**
   * From is where a Haul's stock starts, or where a Carry's downed
   * character lies now.
   */
  from?: string;
  /**
   * Reward is the coin on offer; a proposal's is what is pledged so far.
   */
  reward: number /* int64 */;
  mode: string;
  cap?: number /* int64 */;
  lifetime: string;
  turnover: string;
  state: string;
  progress: number /* int64 */;
  count: number /* int64 */;
  claims: number /* int64 */;
  need?: number /* int64 */;
  pledged?: number /* int64 */;
  /**
   * Left is ticks until it expires; 0 for none.
   */
  left?: number /* int64 */;
  mine: boolean;
  /**
   * Yours is the character's own progress toward it.
   */
  yours: number /* int64 */;
  top: Contribution[];
  hauler?: string;
  vow?: boolean;
  /**
   * Even: a pooled goal pays everyone the same, not by contribution.
   */
  even?: boolean;
  /**
   * Evolved marks the world day its target evolved, when its issuer may
   * withdraw it whatever has been claimed.
   */
  evolved?: boolean;
  /**
   * Takes are the goods the viewer carries that a Deliver still takes
   * from it; Haul is whether the viewer may take its stock here, or
   * deliver it here.
   */
  takes: Goods[];
  haul?: string; // take, deliver
  building?: string; // the structure a raise goal builds
  /**
   * Paid are a met goal's claims, each with the facts it cites.
   */
  paid?: GoalClaim[];
}
/**
 * GoalClaim is one claim on a met goal: who, for how much, and the facts
 * that met it. Cited counts every fact; Facts are those still at hand.
 */
export interface GoalClaim {
  who: string;
  units: number /* int64 */;
  coin: number /* int64 */;
  cited: number /* int64 */;
  facts: Fact[];
}
/**
 * Contribution is a contributor's units toward a goal.
 */
export interface Contribution {
  who: string;
  units: number /* int64 */;
}
/**
 * Draft is a goal the board suggests from the state of the world.
 */
export interface Draft {
  why: string;
  spec: GoalSpec;
}
/**
 * Goals is /goals for a character: the board of the settlement it stands
 * in, drafts, its own goals wherever they hang and the rules a post is
 * checked against. Away from a settlement Settlement is -1 and only Mine
 * is filled.
 */
export interface Goals {
  settlement: number /* int */;
  name: string;
  board: Goal[];
  drafts: Draft[];
  mine: Goal[];
  met: Goal[]; // the latest goals met on this board
  live: number /* int64 */;
  limit: number /* int64 */;
  fee: number /* int64 */; // per cent of the reward
  feeLeast: number /* int64 */;
  rewardLeast: number /* int64 */;
  pledgeNeed: number /* int64 */;
  eachCap: number /* int64 */; // the most claimants an Each goal pays
  verbs: string[];
  officer: boolean;
  coin: number /* int64 */;
  banner: string;
  /**
   * Targets are what each verb may be posted against from here; Line,
   * Within and Ephemeral are the defaults the form fills in: a Hold's
   * threat line, a Discover's reach in tiles, an ephemeral goal's ticks.
   */
  targets: Targets[];
  line: number /* int64 */;
  within: number /* int64 */;
  ephemeral: number /* int64 */;
  at: Hex;
  /**
   * What the form may narrow a goal by: a trait a made item must carry,
   * a region the creature must be defeated in, a generated field a
   * discovered tile must reach, and the things a vow may hold off.
   */
  traits: Pick[];
  places: Pick[];
  fields: Pick[];
  vows: Pick[];
  /**
   * Party are the characters standing here a party goal may name, and
   * PartyMost how many it may.
   */
  party: Pick[];
  partyMost: number /* int64 */;
  /**
   * Even: the character may post a pooled goal that pays everyone the
   * same (GDD 5.9).
   */
  even: boolean;
  /**
   * Waiting are goods goals handed the character that wait where they
   * were handed over; it takes them by acting there.
   */
  waiting: Waiting[];
}
/**
 * Waiting is goods that wait for a character at a place.
 */
export interface Waiting {
  place: string;
  goods: Goods[];
}
/**
 * Targets are the choices a verb offers on the posting form.
 */
export interface Targets {
  verb: string;
  options: Pick[];
}
/**
 * Pick is one option of a select: the value sent and what it shows.
 */
export interface Pick {
  value: string;
  label: string;
}
/**
 * Board is every settlement's notice-board goals, for the forum: a post
 * per goal, its progress edited on a timer.
 */
export interface Board {
  tick: number /* int64 */;
  /**
   * Every is the least ticks between two edits of one post.
   */
  every: number /* int64 */;
  posts: BoardPost[];
}
/**
 * BoardPost is one goal's forum post.
 */
export interface BoardPost {
  settlement: number /* int */;
  name: string;
  banner: string; // a media key
  goal: Goal;
}
/**
 * CostLine is goods of a tag, or coin when the tag is empty.
 */
export interface CostLine {
  tag?: string;
  quantity: number /* int64 */;
}
/**
 * Structure is one of a settlement's structures (GDD 4.16).
 */
export interface Structure {
  kind: string;
  name: string;
  tier: number /* int64 */;
  maxTier: number /* int64 */;
  condition: number /* int64 */;
  closed: boolean;
  raising: boolean;
  next?: CostLine[];
  /**
   * CanRaise: goals raise it a tier, no raise of it is open and the
   * system that reads that tier is built.
   */
  canRaise: boolean;
  /**
   * Waits is the milestone its next raise waits for, if its system is not
   * built yet.
   */
  waits?: string;
}
/**
 * Settlement is a settlement a guild runs.
 */
export interface Settlement {
  n: number /* int */;
  name: string;
  treasury: number /* int64 */;
  structures: Structure[];
  here: boolean;
  /**
   * ConditionMax is a structure's condition in full repair.
   */
  conditionMax: number /* int64 */;
}
/**
 * GuildMember is one member on the guild's page.
 */
export interface GuildMember {
  id: string;
  name: string;
  leader: boolean;
  officer: boolean;
  admin: boolean;
  draw: boolean; // may withdraw past what its deposits earn
  put: number /* int64 */; // contribution, all time
  season: number /* int64 */; // this season
}
/**
 * GuildWork is a work and its stock (GDD 4.14).
 */
export interface GuildWork {
  id: string;
  name: string;
  on: boolean;
  days: number /* int64 */; // days of stock left in the bank
  uses: CostLine[];
  gives: string;
  by: number /* int64 */;
  needs?: string;
  waits?: string;
  can: boolean; // may be switched on here
  /**
   * Spares says the work gives coin its members keep; Ran, Used and Gave
   * are then the world days it has been stocked here since it was
   * switched on, and the coin value it has consumed and spared in them.
   */
  spares?: boolean;
  ran?: number /* int64 */;
  used?: number /* int64 */;
  gave?: number /* int64 */;
}
/**
 * Approval is a payment waiting for a second officer.
 */
export interface Approval {
  id: string;
  by: string;
  to: string;
  what: string;
  value: number /* int64 */;
  /**
   * Goods marks a payment out of the bank, approved where the bank is.
   */
  goods: boolean;
}
/**
 * GuildVote is an open motion.
 */
export interface GuildVote {
  target: string;
  role: string;
  for: number /* int64 */;
  need: number /* int64 */;
}
/**
 * Charter is whether the character's tile can be chartered, and what it
 * costs (GDD 4.8).
 */
export interface Charter {
  can: boolean;
  why?: string;
  take: boolean; // a starting settlement taken over
  coin: number /* int64 */;
  timber: number /* int64 */;
  stone: number /* int64 */;
  fields?: { [key: string]: number /* int64 */ }; // a Surveyor's view
}
/**
 * Guild is /guild: a character's guild, or what founding one takes.
 */
export interface Guild {
  id?: string;
  name?: string;
  server: boolean;
  leader?: string;
  members: GuildMember[];
  /**
   * Officers are those who may spend and approve: the leader, a server's
   * admins and the officers named. Named of OfficersMax are named.
   */
  officers: number /* int64 */;
  named: number /* int64 */;
  officersMax: number /* int64 */;
  full: boolean;
  least: number /* int64 */;
  treasury: number /* int64 */;
  bank: Goods[];
  /**
   * BankHere: the character stands in a settlement the guild runs, where
   * goods go into and out of the bank; coin moves from anywhere.
   */
  bankHere: boolean;
  works: GuildWork[];
  settlements: Settlement[];
  approvals: Approval[];
  votes: GuildVote[];
  invites: Pick[]; // guilds that invited the character
  /**
   * Near are characters standing with an officer whom it could invite.
   */
  near: Pick[];
  officer: boolean;
  spend: number /* int64 */; // what an officer may still pay today
  /**
   * DrawShare is the per cent of its gifts a member may draw at cost.
   */
  drawShare: number /* int64 */;
  charter: Charter;
  banner: string;
}
/**
 * Need is one threshold of a class's unlock and how far along it is.
 */
export interface Need {
  what: string;
  have: number /* int64 */;
  at: number /* int64 */;
}
/**
 * Ability is one entry of a tree.
 */
export interface Ability {
  id: string;
  name: string;
  text: string;
  taken: boolean;
  waits?: string;
}
/**
 * Tier is one tier of a tree: the level it opens at and its two
 * abilities.
 */
export interface Tier {
  level: number /* int64 */;
  open: boolean;
  options: Ability[];
}
/**
 * Class is one class as /classes shows it.
 */
export interface Class {
  id: string;
  name: string;
  leans: string;
  earned: boolean;
  active: boolean;
  first: boolean;
  level: number /* int64 */;
  needs: Need[];
  tiers: Tier[];
}
/**
 * Classes is /classes: every class found so far, earned or not, and how
 * many may be active.
 */
export interface Classes {
  classes: Class[];
  active: number /* int64 */;
  most: number /* int64 */;
  /**
   * Here is whether the character stands in a settlement, where classes
   * are chosen.
   */
  here: boolean;
  /**
   * Prey is set for a character with Mark prey.
   */
  prey?: Prey;
}
/**
 * Prey is a Stalker's mark (GDD 5.9): the creature tags it may name and
 * the one it named today.
 */
export interface Prey {
  tags: string[];
  today?: string;
}

